PREFIX oncologia: <https://w3id.org/rastro/oncologia#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?name WHERE {
  {
    SELECT ?name (COUNT(DISTINCT ?t) AS ?n) WHERE {
      ?pulmon rdfs:label "Lung Neoplasms"@en .
      ?t oncologia:condition ?c . ?c oncologia:within ?pulmon .
      ?t oncologia:status ?st . FILTER(?st IN ("TERMINATED","WITHDRAWN"))
      ?t oncologia:sponsor ?s . ?s oncologia:industry true . ?s oncologia:name ?name .
    } GROUP BY ?name
  }
} ORDER BY DESC(?n) LIMIT 3
